import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-biochemistry-lipid-metabolism-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What are ketone bodies?`]: {
    question: r`On day 4 of a fast, a volunteer's blood carries a rising level of a water-soluble fuel, other than glucose, that was nearly absent after meals and that the brain has begun to burn. Where does this fuel come from?`,
    options: [r`Liver, built from lactate sent over by working muscle`, r`Adipose, released as glycerol from stored triglyceride`, r`Liver, built from surplus acetyl-CoA of fat oxidation`, r`Muscle, released as alanine from protein breakdown`],
    correctAnswer: 2,
    explanation: r`The fuel is a ketone body such as acetoacetate or β-hydroxybutyrate, which the liver makes when fatty acid oxidation supplies more acetyl-CoA than the citric acid cycle can take. Lactate and alanine are carbon sources for making glucose, not a new fuel that appears only in fasting. Glycerol is also a glucose precursor and is not burned by the brain.`,
  },
  [r`How many ATP from a 16-carbon fatty acid (palmitate)?`]: {
    question: r`Stearate is a saturated 18-carbon fatty acid. Count its rounds of β-oxidation and its acetyl-CoA, then use 4 ATP per round, 10 ATP per acetyl-CoA, and an activation cost of 2 ATP. What is the net yield?`,
    options: [r`120 ATP`, r`122 ATP`, r`124 ATP`, r`106 ATP`],
    correctAnswer: 0,
    explanation: r`Eighteen carbons give 9 acetyl-CoA from 8 rounds, so the yield is 8 × 4 + 9 × 10 = 122, and subtracting 2 for activation leaves 120. Stopping at 122 forgets the activation cost. A total of 124 comes from counting 9 rounds, one per acetyl-CoA, and 106 is the figure for 16-carbon palmitate.`,
  },
  [r`What is β-oxidation?`]: {
    question: r`A saturated 12-carbon fatty acyl-CoA in the mitochondrial matrix is cleaved completely by β-oxidation. What does the pathway itself produce, before any acetyl-CoA enters the citric acid cycle?`,
    options: [r`6 NADH, 6 FADH₂ and 6 acetyl-CoA`, r`5 NADH, 5 FADH₂ and 6 acetyl-CoA`, r`5 NADH, 5 FADH₂ and 5 acetyl-CoA`, r`6 NADH, 6 FADH₂ and 12 acetyl-CoA`],
    correctAnswer: 1,
    explanation: r`Twelve carbons make 6 two-carbon units, but only 5 cleavages are needed because the last round splits a four-carbon chain into two acetyl-CoA. Each round gives one NADH and one FADH₂, so the totals are 5, 5 and 6. Counting 6 rounds adds a round that never happens, counting 5 acetyl-CoA loses the final two-carbon piece, and 12 acetyl-CoA treats each carbon as a unit.`,
  },
  [r`The primary product released in each cycle of beta-oxidation is:`]: {
    question: r`A fatty acyl-CoA carries ¹⁴C only at carbon 1 (the carbon bonded to CoA) and carbon 2. After exactly one round of β-oxidation, where is the label?`,
    options: [r`Both labeled carbons are in the shortened acyl-CoA`, r`Carbon 1 has left as CO₂ and carbon 2 is in acyl-CoA`, r`Carbon 1 is in acetyl-CoA and carbon 2 is in acyl-CoA`, r`Both labeled carbons are in the released acetyl-CoA`],
    correctAnswer: 3,
    explanation: r`Each round cuts between carbons 2 and 3, releasing carbons 1 and 2 together as acetyl-CoA and leaving an unlabeled chain two carbons shorter. Placing the label in the shortened chain cuts from the wrong end. No CO₂ is released by β-oxidation itself, and the cut does not fall between carbons 1 and 2.`,
  },
  [r`During prolonged fasting, which tissue cannot directly use fatty acids as its major fuel and instead relies heavily on glucose/ketones?`]: {
    question: r`Albumin-bound ¹⁴C-palmitate is infused into a fasting animal. Labeled CO₂ is soon produced by heart, skeletal muscle and liver, but almost none by brain. What best explains the brain result?`,
    options: [r`Neurons have too few mitochondria for oxidative metabolism`, r`Brain cells lack the enzymes of the citric acid cycle`, r`Long-chain fatty acids barely cross the blood-brain barrier`, r`Fasting brain takes its energy from anaerobic glycolysis`],
    correctAnswer: 2,
    explanation: r`Long-chain fatty acids do not cross the blood-brain barrier to any useful extent, so the brain depends on glucose and, in a fast, on ketone bodies. Neurons are rich in mitochondria and run the citric acid cycle at a high rate. The brain is strongly aerobic, so anaerobic glycolysis is not its fasting energy source.`,
  },
  [r`Beta-oxidation of fatty acids produces:`]: {
    question: r`Isolated mitochondria are given palmitoyl-carnitine while citrate synthase is blocked, so nothing enters the citric acid cycle. Which products are still formed from the fatty acid?`,
    options: [r`Acetyl-CoA, CO₂ and NADPH, with no FADH₂ formed`, r`Acetyl-CoA, NADH and FADH₂, with no CO₂ released`, r`CO₂, NADH and GTP, with no acetyl-CoA released`, r`Pyruvate, NADH and ATP, with no acetyl-CoA formed`],
    correctAnswer: 1,
    explanation: r`β-Oxidation by itself makes acetyl-CoA plus one NADH and one FADH₂ per round, and it needs no citric acid cycle to do so. CO₂ and GTP come only from the cycle, which is blocked here. NADPH belongs to fatty acid synthesis, and pyruvate is a product of glycolysis, not of fat breakdown.`,
  },
  [r`Which vitamins are fat-soluble?`]: {
    question: r`For a year, a person takes very large daily doses of four vitamins: C, thiamine (B1), folate and A. Which one is most likely to build up to a toxic level, and why?`,
    options: [r`Vitamin C, because it is fat-soluble and stored in tissue`, r`Thiamine, because it is water-soluble and held in plasma`, r`Vitamin A, because it is fat-soluble and stored in tissue`, r`Folate, because it is water-soluble and held in plasma`],
    correctAnswer: 2,
    explanation: r`Vitamins A, D, E and K dissolve in fat, so excess is stored in liver and adipose tissue instead of being excreted, and it can reach toxic levels. Vitamin C is water-soluble, not fat-soluble. Thiamine and folate are water-soluble too, which means the excess is lost in urine instead of accumulating.`,
  },
  [r`Which cofactor does fatty acid synthesis use as reducing power?`]: {
    question: r`Purified fatty acid synthase is mixed with acetyl-CoA and malonyl-CoA, but no palmitate forms until one more component is added. Which component is it?`,
    options: [r`NADH, the electron donor for its two reduction steps`, r`FAD, the electron acceptor for its two oxidation steps`, r`NAD⁺, the electron acceptor for its two oxidation steps`, r`NADPH, the electron donor for its two reduction steps`],
    correctAnswer: 3,
    explanation: r`Fatty acid synthesis is reductive and takes its electrons from NADPH, most of which comes from the pentose phosphate pathway. NADH is the reduced cofactor of catabolism and is not used by the synthase. FAD and NAD⁺ accept electrons in β-oxidation, the opposite pathway, and synthesis has no oxidation steps.`,
  },
  [r`Insulin promotes lipid storage by:`]: {
    question: r`A patient has an insulin-secreting tumor, so insulin stays high even after an overnight fast. Compared with a healthy fasting person, what is expected in this patient's adipose tissue and plasma?`,
    options: [r`Lipoprotein lipase down, hormone-sensitive lipase up, high free fatty acids`, r`Lipoprotein lipase up, hormone-sensitive lipase up, high free fatty acids`, r`Lipoprotein lipase down, hormone-sensitive lipase down, low free fatty acids`, r`Lipoprotein lipase up, hormone-sensitive lipase down, low free fatty acids`],
    correctAnswer: 3,
    explanation: r`Insulin activates lipoprotein lipase, which pulls fatty acids from circulating lipoproteins into adipocytes, and it inhibits hormone-sensitive lipase, which would release stored fat. Plasma free fatty acids therefore stay low. The pattern with lipoprotein lipase down and hormone-sensitive lipase up is the normal fasting state, and the two mixed patterns have insulin pushing storage and release in the same cell at once.`,
  },
  [r`Beta oxidation produces how much ATP per cycle (approximate)?`]: {
    question: r`A fatty acyl-CoA passes through three rounds of β-oxidation. Using 2.5 ATP per NADH and 1.5 ATP per FADH₂, how much ATP do the reduced cofactors of those rounds give, not counting any acetyl-CoA?`,
    options: [r`12 ATP`, r`7.5 ATP`, r`30 ATP`, r`42 ATP`],
    correctAnswer: 0,
    explanation: r`Each round gives one NADH and one FADH₂, worth 2.5 + 1.5 = 4 ATP, so three rounds give 12. An answer of 7.5 counts only the NADH. An answer of 30 is the yield of the three acetyl-CoA in the citric acid cycle, which the question excludes, and 42 adds that 30 to the 12.`,
  },
  [r`Phospholipids are amphipathic, meaning they have:`]: {
    question: r`A synthetic molecule has a charged phosphate group at one end and two 16-carbon hydrocarbon chains at the other. When it is shaken in water, what does it most likely form?`,
    options: [r`Sheets two molecules thick, charged groups inside and chains facing water`, r`A clear solution of single molecules, each one fully surrounded by water`, r`Sheets two molecules thick, chains inside and charged groups facing water`, r`A floating oil layer of single molecules, each one fully excluding water`],
    correctAnswer: 2,
    explanation: r`A molecule with a polar head and nonpolar tails is amphipathic, so in water it packs into a bilayer that buries the chains and leaves the charged groups in contact with water. Turning the bilayer inside out would expose the chains to water, which is unfavorable. A true solution ignores the two long chains, and a plain oil layer ignores the charged head.`,
  },
  [r`Trans fats are harmful partly because they:`]: {
    question: r`Partial hydrogenation of a liquid vegetable oil converts some of its cis double bonds to trans. How does the product differ from the starting oil, both in the tub and in the blood of a person who eats it regularly?`,
    options: [r`Firmer at room temperature; it lowers LDL and raises HDL`, r`Runnier at room temperature; it raises LDL and lowers HDL`, r`Firmer at room temperature; it raises LDL and lowers HDL`, r`Runnier at room temperature; it lowers LDL and raises HDL`],
    correctAnswer: 2,
    explanation: r`A trans double bond leaves the chain nearly straight, so trans fats pack tightly like saturated fats and are firmer. They also raise LDL and lower HDL, the worst combination for heart disease. The runnier choices apply to cis bonds, whose kinks prevent packing, and the choices with LDL falling give the lipid effect backward.`,
  },
  [r`Cholesterol in the plasma membrane:`]: {
    question: r`Two artificial membranes are made from the same phospholipid, one with cholesterol and one without. Their fluidity is measured at 5 °C and at 45 °C. Compared with the cholesterol-free membrane, the one with cholesterol is:`,
    options: [r`less fluid at 5 °C and more fluid at 45 °C`, r`more fluid at 5 °C and less fluid at 45 °C`, r`more fluid at 5 °C and more fluid at 45 °C`, r`less fluid at 5 °C and less fluid at 45 °C`],
    correctAnswer: 1,
    explanation: r`Cholesterol buffers fluidity: in the cold it keeps the chains from packing tightly, and in the heat its rigid rings restrain their motion. The reversed answer would make cholesterol exaggerate temperature changes instead of damping them. The two one-direction answers treat cholesterol as a simple fluidizer or a simple stiffener, which is true at only one end of the range.`,
  },
  [r`Statins raise {{c1::SREBP-2}} activity in hepatocytes, upregulating {{c2::LDL receptors}} — the main mechanism lowering plasma LDL.`]: {
    question: r`A patient with homozygous familial hypercholesterolemia has no functional LDL receptor gene. A statin that works well in other patients barely lowers this patient's LDL. Why?`,
    options: [r`Statins act mainly by inducing LDL receptors, and none can be made`, r`Statins cannot inhibit HMG-CoA reductase when plasma LDL is high`, r`Statins act mainly by blocking gut cholesterol uptake, which is intact`, r`Statins act mainly by raising HDL, which cannot remove LDL from blood`],
    correctAnswer: 0,
    explanation: r`By lowering hepatocyte cholesterol, a statin activates SREBP-2, which raises LDL receptor expression, and the extra receptors clear LDL from blood. With no working receptor gene, that response has nothing to act on. The enzyme is still inhibited whatever the plasma LDL is, and statins do not work through gut uptake or through HDL.`,
  },
  [r`The cholesterol ring cannot be degraded for energy. What are its three major metabolic fates, and which is quantitatively dominant?`]: {
    question: r`A volunteer is given cholesterol labeled with ¹⁴C in its ring carbons. Over the following weeks, where is most of the label recovered?`,
    options: [r`In breath as CO₂, after the ring is burned for ATP`, r`In urine as breakdown products of steroid hormones`, r`In stool as bile acids, with the ring still intact`, r`In urine as ketone bodies made from ring carbons`],
    correctAnswer: 2,
    explanation: r`Humans cannot break the sterol ring for energy, so cholesterol leaves mainly by conversion to bile acids, which are lost in stool with the ring intact. Labeled CO₂ would require ring oxidation, which does not occur. Steroid hormones are a real fate but a tiny one in quantity, and ring carbons are never converted to ketone bodies.`,
  },
  [r`Sphingolipids share a {{c1::ceramide}} core: + phosphocholine = {{c2::sphingomyelin}}; + sialylated sugars = {{c3::gangliosides}}.`]: {
    question: r`A membrane lipid is hydrolyzed completely and yields sphingosine, one fatty acid, phosphate and choline, with no glycerol and no sugar. Which lipid was it?`,
    options: [r`A ganglioside: ceramide plus sialylated sugars`, r`Phosphatidylcholine: ceramide plus phosphocholine`, r`Sphingomyelin: ceramide plus phosphocholine`, r`A plasmalogen: ceramide plus an ether-linked chain`],
    correctAnswer: 2,
    explanation: r`Sphingosine with an amide-linked fatty acid is ceramide, and ceramide with phosphocholine is sphingomyelin. A ganglioside would release sugars including sialic acid, and none were found. Phosphatidylcholine and plasmalogens are built on glycerol, not ceramide, so both would release glycerol.`,
  },
  [r`How does the SREBP-SCAP-Insig system sense cholesterol levels?`]: {
    question: r`A cell line carries a mutant SCAP that can no longer bind Insig but is otherwise normal. The cells are loaded with cholesterol. What is expected?`,
    options: [r`SREBP is held in the ER, so reductase and LDL receptor genes are switched off`, r`SREBP is still cleaved in the Golgi, so reductase and LDL receptor genes stay on`, r`SREBP is still cleaved in the Golgi, so reductase and LDL receptor genes switch off`, r`SREBP is held in the ER, so reductase and LDL receptor genes are switched on`],
    correctAnswer: 1,
    explanation: r`High cholesterol normally works by making Insig hold the SCAP-SREBP complex in the ER. Without Insig binding, SCAP keeps escorting SREBP to the Golgi, where it is cleaved and goes on to induce HMG-CoA reductase and the LDL receptor even though cholesterol is plentiful. Holding SREBP in the ER is the normal response that this mutant has lost, and cleaved SREBP turns its target genes on, not off.`,
  },
  [r`Which phospholipid dominates pulmonary surfactant, and what ratio marks fetal lung maturity?`]: {
    question: r`Amniotic fluid sampled at 31 weeks of gestation has a lecithin-to-sphingomyelin ratio of 1.0. What does this predict for the baby if delivered now?`,
    options: [r`Immature lungs: too little surfactant to lower alveolar surface tension`, r`Mature lungs: enough surfactant to lower alveolar surface tension`, r`Immature lungs: too much surfactant, which raises surface tension`, r`Mature lungs: sphingomyelin is the main lipid of lung surfactant`],
    correctAnswer: 0,
    explanation: r`Maturity is marked by a ratio of about 2 or more, reflecting the late rise in dipalmitoylphosphatidylcholine made by type II pneumocytes. A ratio of 1.0 means too little of it, so alveoli tend to collapse and respiratory distress syndrome is likely. Surfactant lowers surface tension, it does not raise it, and its main lipid is the lecithin, not sphingomyelin.`,
  },
  [r`Tay-Sachs disease is a deficiency of {{c1::hexosaminidase A}} accumulating {{c2::GM2 ganglioside}}; Gaucher disease lacks {{c3::glucocerebrosidase}}.`]: {
    question: r`A child has a greatly enlarged liver and spleen, episodes of bone pain, and macrophages whose cytoplasm looks like crinkled paper. The retina is normal. Which lysosomal defect fits?`,
    options: [r`Hexosaminidase A deficiency, storing GM2 ganglioside`, r`Glucocerebrosidase deficiency, storing glucocerebroside`, r`Glucocerebrosidase deficiency, storing GM2 ganglioside`, r`Hexosaminidase A deficiency, storing glucocerebroside`],
    correctAnswer: 1,
    explanation: r`Enlarged liver and spleen, bone crises and crinkled-paper macrophages describe Gaucher disease, which lacks glucocerebrosidase and so stores its substrate, glucocerebroside. Hexosaminidase A deficiency is Tay-Sachs disease, which stores GM2 ganglioside and gives neurodegeneration with a cherry-red macula and no organ enlargement. The mixed choices pair an enzyme with the wrong stored lipid.`,
  },
  [r`FA synthesis: {{c1::cytosol}}, {{c2::NADPH}}, ACP carrier; beta-oxidation: {{c3::mitochondria}}, FAD/$NAD^+$, CoA carrier.`]: {
    question: r`After cell fractionation, fraction 1 turns labeled acetyl-CoA into palmitate when given NADPH. Fraction 2 shortens palmitoyl-CoA while reducing FAD and NAD⁺. Which compartments are they?`,
    options: [r`Fraction 1 is cytosol; fraction 2 is mitochondria`, r`Fraction 1 is mitochondria; fraction 2 is cytosol`, r`Both fractions are cytosol at different pH`, r`Both fractions are mitochondria, matrix and membrane`],
    correctAnswer: 0,
    explanation: r`Fatty acid synthesis runs in the cytosol with NADPH, and β-oxidation runs in mitochondria with FAD and NAD⁺ as electron acceptors. The reversed answer swaps the two compartments. Putting both in one compartment would let synthesis and breakdown run side by side, which the cell avoids by separating them.`,
  },
  [r`Summarize insulin's coordinated lipid actions in the fed state versus the counter-regulatory fasting pattern.`]: {
    question: r`A runner who skipped breakfast is two hours into a race, with low insulin and high glucagon and epinephrine. Which pair of changes is expected?`,
    options: [r`Adipose hormone-sensitive lipase is inhibited and liver ACC is active`, r`Adipose hormone-sensitive lipase is active and liver ACC is active`, r`Adipose hormone-sensitive lipase is inhibited and liver ACC is inhibited`, r`Adipose hormone-sensitive lipase is active and liver ACC is inhibited`],
    correctAnswer: 3,
    explanation: r`Fasting hormones push every step toward fat use: lipolysis is switched on in adipose, and acetyl-CoA carboxylase (ACC) is switched off in liver so malonyl-CoA falls and β-oxidation can run. The lipase-inhibited, ACC-active pattern is the insulin-driven fed state. The two mixed patterns would have one hormone state releasing and building fat at once, which the coordinated control prevents.`,
  },
  [r`Besides CPT-1, how is flux through beta-oxidation itself throttled when the ETC is already saturated?`]: {
    question: r`In working muscle, oxygen delivery drops, the electron transport chain backs up, and the mitochondrial NADH/NAD⁺ ratio climbs. How does this directly slow β-oxidation?`,
    options: [r`NADH inhibits carnitine palmitoyltransferase 1`, r`NADH inhibits 3-hydroxyacyl-CoA dehydrogenase`, r`NAD⁺ inhibits 3-hydroxyacyl-CoA dehydrogenase`, r`NADH activates acetyl-CoA carboxylase in the matrix`],
    correctAnswer: 1,
    explanation: r`The NAD⁺-linked step of β-oxidation is inhibited by its own product, NADH, so the pathway slows when electrons have nowhere to go. Carnitine palmitoyltransferase 1 is controlled by malonyl-CoA, not NADH. NAD⁺ is the substrate of the dehydrogenase, not its inhibitor, and acetyl-CoA carboxylase is a cytosolic enzyme of synthesis.`,
  },
  [r`Where does plasmalogen (ether lipid) synthesis begin, and why does that localization matter clinically?`]: {
    question: r`An infant has Zellweger syndrome, in which functional peroxisomes fail to form. Which pair of lipid findings is expected?`,
    options: [r`Low very-long-chain fatty acids and high plasmalogens`, r`High very-long-chain fatty acids and high plasmalogens`, r`Low very-long-chain fatty acids and low plasmalogens`, r`High very-long-chain fatty acids and low plasmalogens`],
    correctAnswer: 3,
    explanation: r`Peroxisomes shorten very-long-chain fatty acids and carry out the first steps of plasmalogen synthesis. Without them the fatty acids pile up and the ether lipids, which are abundant in myelin, cannot be made, hence the severe neurologic disease. Each other choice gets at least one of the two directions backward.`,
  },
  [r`Odd-chain FAs: propionyl-CoA is carboxylated ({{c1::biotin}}), then a {{c2::B12}}-dependent mutase yields {{c3::succinyl-CoA}}.`]: {
    question: r`A man who eats many raw egg whites becomes biotin deficient (a protein in raw egg white binds biotin). When he then oxidizes odd-chain fatty acids, which intermediate builds up, and why?`,
    options: [r`Propionyl-CoA, because its carboxylase needs biotin`, r`Methylmalonyl-CoA, because its mutase needs biotin`, r`Propionyl-CoA, because its carboxylase needs B12`, r`Succinyl-CoA, because its synthetase needs biotin`],
    correctAnswer: 0,
    explanation: r`The last three carbons of an odd-chain fatty acid leave as propionyl-CoA, which a biotin-dependent carboxylase converts to methylmalonyl-CoA. Without biotin, propionyl-CoA accumulates. The mutase that acts next depends on vitamin B12, not biotin, so methylmalonyl-CoA builds up in B12 deficiency instead, and succinyl-CoA is the end product that would be short, not in excess.`,
  },
  [r`{{c1::Malonyl-CoA}} inhibits {{c2::carnitine palmitoyltransferase 1 (CPT-1)}}, preventing simultaneous fatty acid synthesis and oxidation.`]: {
    question: r`A mouse expresses a CPT-1 that works normally but can no longer bind malonyl-CoA. In its liver after a large carbohydrate meal, what goes wrong?`,
    options: [r`Fatty acid synthesis halts because acetyl-CoA carboxylase loses its activator`, r`Long-chain fatty acids can no longer be carried into mitochondria at all`, r`Newly made fatty acids enter mitochondria and are oxidized, a futile cycle`, r`Ketone bodies can no longer be produced by the liver in a later fast`],
    correctAnswer: 2,
    explanation: r`Malonyl-CoA, the first intermediate of fatty acid synthesis, normally blocks CPT-1 so that new fatty acids are not carried into mitochondria and burned. Remove that block and synthesis and oxidation run at the same time. Acetyl-CoA carboxylase is activated by citrate, not by CPT-1, and transport and ketone production would be unimpaired because the enzyme itself still works.`,
  },
  [r`Carnitine shuttle order: {{c1::CPT-1}} (outer membrane), {{c2::translocase}}, then {{c3::CPT-2}} regenerating acyl-CoA in the matrix.`]: {
    question: r`A patient lacks CPT-2 but has normal CPT-1 and a normal carnitine-acylcarnitine translocase. Where do long-chain acyl groups get stuck?`,
    options: [r`As acyl-CoA in the cytosol, never transferred onto carnitine`, r`As acylcarnitine in the cytosol, unable to cross into the matrix`, r`As acyl-CoA in the matrix, unable to start β-oxidation`, r`As acylcarnitine in the matrix, not converted back to acyl-CoA`],
    correctAnswer: 3,
    explanation: r`CPT-1 on the outer membrane makes acylcarnitine, the translocase carries it across the inner membrane, and CPT-2 on the matrix side hands the acyl group back to CoA. Losing CPT-2 strands the acyl group on carnitine after it has crossed. A cytosolic acyl-CoA block is CPT-1 deficiency, a cytosolic acylcarnitine block is translocase deficiency, and matrix acyl-CoA never forms here.`,
  },
  [r`Mitochondrial acetyl-CoA reaches the cytosol for fatty acid synthesis as {{c1::citrate}}, cleaved there by {{c2::ATP-citrate lyase}}.`]: {
    question: r`Acetyl-CoA labeled with ¹⁴C is produced inside the mitochondria of a well-fed hepatocyte, and the label later appears in cytosolic palmitate. In what form did the labeled carbon leave the mitochondrion?`,
    options: [r`Citrate, formed from acetyl-CoA and oxaloacetate`, r`Acetyl-CoA, moved out by a CoA transporter`, r`Malonyl-CoA, formed by acetyl-CoA carboxylase`, r`Pyruvate, formed by pyruvate dehydrogenase`],
    correctAnswer: 0,
    explanation: r`Acetyl-CoA cannot cross the inner membrane, so it condenses with oxaloacetate to citrate, which is exported and cleaved by ATP-citrate lyase to give cytosolic acetyl-CoA. There is no transporter for acetyl-CoA itself. Malonyl-CoA is made in the cytosol after export, and pyruvate dehydrogenase is irreversible, so acetyl-CoA cannot be turned back into pyruvate.`,
  },
  [r`Acetyl-CoA carboxylase (biotin) is activated by {{c1::citrate}} and insulin, and inhibited by {{c2::palmitoyl-CoA}} and phosphorylation by {{c3::AMPK}} and PKA.`]: {
    question: r`Acetyl-CoA carboxylase is assayed in four hepatocyte samples. In which sample is the enzyme least active?`,
    options: [r`High citrate, high palmitoyl-CoA, AMPK inactive`, r`Low citrate, high palmitoyl-CoA, AMPK active`, r`Low citrate, low palmitoyl-CoA, AMPK inactive`, r`High citrate, low palmitoyl-CoA, AMPK active`],
    correctAnswer: 1,
    explanation: r`Citrate activates the enzyme, while its end product palmitoyl-CoA and phosphorylation by AMPK inhibit it. Only the sample with low citrate, high palmitoyl-CoA and active AMPK has all three signals pointing toward inhibition. Each other sample keeps at least one activating condition: high citrate, low palmitoyl-CoA or inactive AMPK.`,
  },
  [r`Essential fatty acids: {{c1::linoleic (omega-6)}} and {{c2::alpha-linolenic (omega-3)}}; {{c3::arachidonic}} is conditionally essential.`]: {
    question: r`A patient fed for months by a fat-free intravenous formula develops scaly dermatitis. Adding which fatty acid to the formula corrects the underlying deficiency?`,
    options: [r`Linoleate (18:2, omega-6), which humans cannot make`, r`Oleate (18:1, omega-9), which humans cannot make`, r`Palmitate (16:0), which humans cannot make`, r`Stearate (18:0), which humans cannot make`],
    correctAnswer: 0,
    explanation: r`Linoleate and α-linolenate are essential because human enzymes cannot place the double bonds that define omega-6 and omega-3 fatty acids, and their lack causes scaly dermatitis. Oleate is made from stearate by the delta-9 desaturase. Palmitate is the direct product of fatty acid synthase, and stearate is made by elongating it.`,
  },
  [r`What are the two cytosolic sources of NADPH for fatty acid synthesis?`]: {
    question: r`In a hepatocyte making fat, exported citrate is cleaved, and the oxaloacetate released is reduced to malate. Which next step both returns the carbon toward the mitochondrion and helps pay for fatty acid synthesis?`,
    options: [r`Malic enzyme converts malate to pyruvate, consuming NADPH`, r`Malate dehydrogenase converts malate to citrate, producing NADH`, r`Malic enzyme converts malate to pyruvate, producing NADPH`, r`Pyruvate carboxylase converts malate to pyruvate, producing ATP`],
    correctAnswer: 2,
    explanation: r`Malic enzyme oxidatively decarboxylates cytosolic malate to pyruvate and makes NADPH, the second source of reducing power for synthesis alongside the pentose phosphate pathway. It produces NADPH, it does not consume it. Malate dehydrogenase makes oxaloacetate, not citrate, and pyruvate carboxylase acts on pyruvate and uses ATP.`,
  },
  [r`Where do elongation and desaturation of palmitate occur, and what is the key limit of human desaturases?`]: {
    question: r`A human liver cell is given stearate (18:0) and no other fatty acid. Which unsaturated fatty acid can its own enzymes make from it?`,
    options: [r`Linoleate, 18:2 with cis bonds at delta-9 and delta-12`, r`An 18:1 fatty acid with a cis double bond at delta-15`, r`Alpha-linolenate, 18:3 with bonds at delta-9, 12 and 15`, r`Oleate, 18:1 with a cis double bond at delta-9`],
    correctAnswer: 3,
    explanation: r`Human desaturases, which sit on the smooth ER, cannot insert a double bond farther than nine carbons from the carboxyl end, so stearate can become oleate. Linoleate and α-linolenate need bonds at delta-12 and delta-15, which is why they are essential in the diet. A single bond at delta-15 is beyond the same limit.`,
  },
  [r`Why do carnitine deficiency and CPT deficiencies present with hypoketotic hypoglycemia during fasting?`]: {
    question: r`A child becomes hypoglycemic after an 18-hour fast. Which additional finding points to a block in the entry of long-chain fatty acids into mitochondria, and not to a normal response to fasting?`,
    options: [r`High blood ketones with high plasma free fatty acids`, r`Low blood ketones with low plasma free fatty acids`, r`High blood ketones with low plasma free fatty acids`, r`Low blood ketones with high plasma free fatty acids`],
    correctAnswer: 3,
    explanation: r`With entry blocked, adipose still releases fatty acids, but the liver cannot oxidize them, so it makes no ketones and has too little ATP and acetyl-CoA to keep gluconeogenesis going. High ketones with high fatty acids is the healthy fasting pattern. Low fatty acids would mean lipolysis itself is suppressed, as with excess insulin, which is a different problem.`,
  },
  [r`What two extra enzymes are needed to beta-oxidize unsaturated fatty acids, and what is the energetic consequence?`]: {
    question: r`Oleoyl-CoA (18:1, cis-Δ9) goes through three normal rounds of β-oxidation, leaving a 12-carbon acyl-CoA whose cis double bond now sits between carbons 3 and 4. What happens in the next round?`,
    options: [r`An isomerase shifts it to trans-Δ2, so this round makes no FADH₂`, r`A reductase saturates it with NADPH, so this round makes two FADH₂`, r`A dehydrogenase oxidizes it with FAD, so this round makes two FADH₂`, r`A thiolase cleaves it directly, so this round makes no NADH`],
    correctAnswer: 0,
    explanation: r`Enoyl-CoA isomerase moves the cis-Δ3 bond to trans-Δ2, the same intermediate that acyl-CoA dehydrogenase would have made, so the FAD step is skipped and one FADH₂ is lost. The NADPH-dependent reductase is needed only for double bonds at even-numbered positions. No round can make two FADH₂, and thiolase acts only after hydration and the NAD⁺ step.`,
  },
  [r`A fasting child has hypoketotic hypoglycemia and elevated C8-C10 acylcarnitines. What enzyme is deficient and why is glucose consumption paradoxically high?`]: {
    question: r`A child with known MCAD deficiency has a stomach virus and has eaten nothing since last night. Which management principle follows from the enzyme defect?`,
    options: [r`Give medium-chain fat, so that the carnitine shuttle is bypassed`, r`Give glucose often, so that fat oxidation is never needed`, r`Give a high-fat diet, so that ketones can replace glucose`, r`Withhold all feeds, so that liver glycogen is conserved`],
    correctAnswer: 1,
    explanation: r`Without medium-chain acyl-CoA dehydrogenase, fat cannot be oxidized past medium chain length, so a fast brings hypoglycemia with no ketones to fall back on. Supplying glucose and avoiding fasting removes the need for the pathway. Medium-chain fat feeds straight into the blocked step, a high-fat diet relies on ketones the liver cannot make, and withholding feeds is exactly what triggers a crisis.`,
  },
  [r`Why is complete oxidation of palmitate worth roughly 106 ATP, and what activation cost is already subtracted?`]: {
    question: r`A student tallies palmitate (16:0) oxidation as 8 rounds of β-oxidation plus 8 acetyl-CoA. With 4 ATP per round and 10 ATP per acetyl-CoA, what is wrong with the tally?`,
    options: [r`There are only 7 acetyl-CoA, so it is 10 ATP too high`, r`There are 9 acetyl-CoA in all, so it is 10 ATP too low`, r`There are 16 rounds in all, so it is 32 ATP too low`, r`There are only 7 rounds, so it is 4 ATP too high`],
    correctAnswer: 3,
    explanation: r`Sixteen carbons give 8 acetyl-CoA, but the seventh round splits a four-carbon chain into two of them, so only 7 rounds occur and the tally has one extra round worth 4 ATP. The acetyl-CoA count of 8 is already right, so 7 and 9 are both miscounts. Sixteen rounds would mean removing one carbon at a time.`,
  },
  [r`Chylomicrons: {{c1::apoB-48}} structural, {{c2::apoC-II}} activates LPL, {{c3::apoE}} mediates remnant uptake.`]: {
    question: r`A patient's chylomicrons are assembled normally and lose their triacylglycerol to tissues at a normal rate, but the shrunken remnants are not taken up by the liver and pile up in plasma. Which apolipoprotein is most likely defective?`,
    options: [r`ApoC-II, the activator of lipoprotein lipase`, r`ApoB-48, the structural protein of the particle`, r`ApoA-I, the activator of the enzyme LCAT`, r`ApoE, the ligand for remnant uptake`],
    correctAnswer: 3,
    explanation: r`Normal assembly shows that apoB-48 is working, and normal triacylglycerol removal shows that apoC-II is activating lipoprotein lipase. What fails is hepatic uptake of the remnant, which depends on apoE. ApoA-I belongs to HDL and activates LCAT, so it plays no part in chylomicron clearance.`,
  },
  [r`Per 2-carbon addition, fatty acid synthase uses one malonyl-CoA and how many NADPH? What is the released terminal product?`]: {
    question: r`Fatty acid synthase starts from an acetyl group and adds two carbons per cycle from malonyl-CoA. How many NADPH has it used by the time the growing chain is 10 carbons long?`,
    options: [r`4 NADPH, from 4 elongation cycles`, r`10 NADPH, from 5 elongation cycles`, r`8 NADPH, from 4 elongation cycles`, r`5 NADPH, from 5 elongation cycles`],
    correctAnswer: 2,
    explanation: r`Going from 2 carbons to 10 takes 4 additions of two carbons, and each cycle has two reduction steps, so 4 × 2 = 8 NADPH. Four NADPH counts only one reduction per cycle. The answers built on 5 cycles forget that the first two carbons come from the acetyl primer, not from an elongation cycle.`,
  },
  [r`Ketone use requires {{c1::thiophorase}} (succinyl-CoA:acetoacetate CoA transferase), which the {{c2::liver}} lacks.`]: {
    question: r`Suppose liver cells were engineered to express thiophorase, the enzyme that other tissues use to activate acetoacetate. What would change during a three-week fast?`,
    options: [r`The liver would make ketones faster, leaving more for the brain`, r`The liver would turn ketones into glucose, raising blood glucose`, r`The liver would export acetyl-CoA itself, replacing the ketones`, r`The liver would burn its own ketones, leaving less for the brain`],
    correctAnswer: 3,
    explanation: r`Thiophorase activates acetoacetate to acetoacetyl-CoA so a tissue can oxidize it, and the liver normally lacks it, which forces every ketone body it makes out to other tissues. A liver with the enzyme would consume part of its own output. The enzyme has no role in making ketones, ketone carbons cannot give net glucose, and acetyl-CoA cannot leave cells.`,
  },
  [r`Trace the VLDL to LDL conversion: what is removed, what remains, and which apolipoprotein persists throughout?`]: {
    question: r`A VLDL particle secreted by the liver is followed in the blood until it has become an LDL particle. Which description of the change is correct?`,
    options: [r`It lost cholesteryl ester, apoC and apoE, and kept its apoB-100`, r`It lost triacylglycerol and apoB-100, and kept apoC and apoE`, r`It lost cholesteryl ester and apoB-100, and gained apoB-48`, r`It lost triacylglycerol, apoC and apoE, and kept its apoB-100`],
    correctAnswer: 3,
    explanation: r`Lipoprotein lipase and then hepatic lipase remove triacylglycerol, and apoC and apoE return to HDL, leaving a small particle rich in cholesteryl ester with its single apoB-100. Cholesteryl ester is what remains, not what is lost. ApoB-100 never leaves the particle and is the ligand for the LDL receptor, and apoB-48 is found only on chylomicrons.`,
  },
  [r`What happens after LDL binds its receptor, and how does familial hypercholesterolemia break this pathway?`]: {
    question: r`Fibroblasts from a patient bind LDL normally at the cell surface, but their receptors cannot gather into clathrin-coated pits. With LDL in the medium, what happens to HMG-CoA reductase activity in these cells?`,
    options: [r`It drops low, because bound LDL signals from the cell surface`, r`It stays high, because no LDL cholesterol arrives to suppress it`, r`It stays high, because bound LDL directly activates the enzyme`, r`It drops low, because the receptors can no longer be recycled`],
    correctAnswer: 1,
    explanation: r`LDL must be taken in by clathrin-mediated endocytosis and broken down in lysosomes before its cholesterol can suppress HMG-CoA reductase. If the receptors cannot be internalized, the cell senses no cholesterol and keeps synthesis high while LDL stays in plasma. Surface binding alone sends no signal, and LDL never activates the enzyme directly.`,
  },
  [r`Lipolysis: {{c1::ATGL}} initiates, HSL continues under {{c2::PKA}} control, and {{c3::insulin}} suppresses it.`]: {
    question: r`A cell-permeable analog of cAMP is added to isolated adipocytes in the absence of any hormone. What is the expected result?`,
    options: [r`PKA phosphorylates hormone-sensitive lipase, and fatty acid release falls`, r`PKA phosphorylates lipoprotein lipase, and fatty acid uptake rises`, r`PKA phosphorylates acetyl-CoA carboxylase, and fat synthesis rises`, r`PKA phosphorylates hormone-sensitive lipase, and fatty acid release rises`],
    correctAnswer: 3,
    explanation: r`cAMP activates PKA, which phosphorylates and activates hormone-sensitive lipase, so stored triacylglycerol is broken down and fatty acids are released. Phosphorylation switches this lipase on, not off. Lipoprotein lipase is raised by insulin, not PKA, and phosphorylation of acetyl-CoA carboxylase inhibits fat synthesis.`,
  },
  [r`One beta-oxidation cycle: oxidation by {{c1::FAD}}, hydration, oxidation by {{c2::$NAD^+$}}, then {{c3::thiolysis}} releasing acetyl-CoA.`]: {
    question: r`An inhibitor blocks the hydration step of β-oxidation (enoyl-CoA hydratase). In the round where the block takes hold, what accumulates, and which cofactor has already been reduced?`,
    options: [r`A trans-enoyl-CoA; FADH₂ has formed but NADH has not`, r`A trans-enoyl-CoA; NADH has formed but FADH₂ has not`, r`A 3-ketoacyl-CoA; both FADH₂ and NADH have formed`, r`A 3-hydroxyacyl-CoA; neither FADH₂ nor NADH has formed`],
    correctAnswer: 0,
    explanation: r`The order is oxidation by FAD, hydration, oxidation by NAD⁺, then thiolysis. Blocking hydration leaves the double-bonded product of the first step, after FADH₂ is made and before the NAD⁺ step can run. Putting NADH first reverses the two oxidations, and the 3-hydroxyacyl and 3-ketoacyl intermediates both lie beyond the blocked step.`,
  },
  [r`Mechanistically, why does fasting (or diabetic) liver divert acetyl-CoA into ketones rather than the TCA cycle?`]: {
    question: r`Liver mitochondria from a fasted animal are oxidizing fatty acids and releasing ketone bodies. Extra oxaloacetate is then supplied to them. What happens to ketone output?`,
    options: [r`It rises: oxaloacetate is converted into acetoacetate`, r`It falls: oxaloacetate directly inhibits β-oxidation`, r`It falls: more acetyl-CoA can enter the cycle as citrate`, r`It rises: oxaloacetate activates HMG-CoA synthase`],
    correctAnswer: 2,
    explanation: r`In fasting liver, oxaloacetate is drained by gluconeogenesis and pushed toward malate by high NADH, so acetyl-CoA has no partner for citrate synthase and overflows into ketone bodies. Restoring oxaloacetate lets acetyl-CoA enter the cycle again. Oxaloacetate is not a ketone precursor, and it does not regulate β-oxidation or HMG-CoA synthase.`,
  },
  [r`HMG-CoA reductase uses {{c1::2 NADPH}} to make {{c2::mevalonate}}; inhibited by AMPK, sterols, and {{c3::statins}}.`]: {
    question: r`A statin is added to a cell extract that makes cholesterol from acetyl-CoA, and synthesis stops. Adding which compound restores cholesterol production with the statin still present?`,
    options: [r`Mevalonate, which lies just after the blocked step`, r`HMG-CoA, which lies just after the blocked step`, r`Acetyl-CoA, which lies just after the blocked step`, r`NADPH, which is the product of the blocked step`],
    correctAnswer: 0,
    explanation: r`Statins inhibit HMG-CoA reductase, which uses 2 NADPH to reduce HMG-CoA to mevalonate, so supplying mevalonate bypasses the block. HMG-CoA is the substrate of the blocked enzyme and acetyl-CoA lies even farther upstream, so both just pile up. NADPH is consumed by the step, not produced by it.`,
  },
  [r`Ketogenesis occurs only in {{c1::liver mitochondria}}, with {{c2::mitochondrial HMG-CoA synthase}} as the rate-limiting enzyme.`]: {
    question: r`A child inherits a complete loss of the mitochondrial isoform of HMG-CoA synthase, while the cytosolic isoform is normal. What is expected?`,
    options: [r`No cholesterol synthesis, but normal ketone bodies in a fast`, r`Normal cholesterol synthesis, but no ketone bodies in a fast`, r`Loss of both cholesterol synthesis and ketone body production`, r`Normal cholesterol synthesis and normal ketone production`],
    correctAnswer: 1,
    explanation: r`Ketone bodies are made in liver mitochondria, where the mitochondrial HMG-CoA synthase is the rate-limiting enzyme, so its loss abolishes ketone production. Cholesterol synthesis uses the separate cytosolic isoform and carries on. Loss of both, or of cholesterol alone, treats the two pools of HMG-CoA as one, and the cytosolic isoform cannot rescue the mitochondrial pathway.`,
  },
  [r`The {{c1::beta-hydroxybutyrate}}/acetoacetate ratio mirrors mitochondrial {{c2::NADH}}; {{c3::acetone}} is exhaled unmetabolized.`]: {
    question: r`A patient in ketoacidosis also goes into shock, so tissues get little oxygen and mitochondrial NADH climbs even higher. What happens to the blood ratio of β-hydroxybutyrate to acetoacetate?`,
    options: [r`It falls, as NADH oxidizes β-hydroxybutyrate to acetoacetate`, r`It rises, as NADH reduces acetoacetate to β-hydroxybutyrate`, r`It rises, as NADH decarboxylates acetoacetate to acetone`, r`It stays fixed, as the two never interconvert in tissues`],
    correctAnswer: 1,
    explanation: r`β-Hydroxybutyrate dehydrogenase keeps the two ketone bodies in balance with the NADH/NAD⁺ ratio, and NADH is the reductant that turns acetoacetate into β-hydroxybutyrate. More NADH therefore raises the ratio. NADH cannot oxidize anything, acetone forms by spontaneous loss of CO₂ without NADH, and the two do interconvert.`,
  },
  [r`In HDL, {{c1::LCAT}} (apoA-I-activated) esterifies cholesterol; {{c2::CETP}} trades cholesteryl esters to apoB particles.`]: {
    question: r`An experimental drug inhibits cholesteryl ester transfer protein (CETP) and nothing else. What change in plasma lipoproteins is expected?`,
    options: [r`HDL cholesteryl ester rises; less is passed to VLDL and LDL`, r`HDL cholesteryl ester falls; more is passed to VLDL and LDL`, r`HDL free cholesterol rises; esterification by LCAT is blocked`, r`HDL cholesteryl ester falls; uptake from cells is blocked`],
    correctAnswer: 0,
    explanation: r`LCAT makes cholesteryl ester inside HDL, and CETP then trades it to apoB-containing particles such as VLDL and LDL. Blocking CETP leaves the ester in HDL, so HDL cholesterol rises. Esterification itself is the job of LCAT, and removal of cholesterol from cells is the job of the ABCA1 transporter, and neither is inhibited here.`,
  },
  [r`Insulin {{c1::upregulates}} lipoprotein lipase in adipose capillaries, and LPL absolutely requires the cofactor {{c2::apoC-II}} on its substrate particle.`]: {
    question: r`A child's plasma looks milky hours after a meal. Lipoprotein lipase taken from the child breaks down chylomicrons from a healthy donor normally, but healthy lipoprotein lipase cannot break down the child's own chylomicrons. What is missing?`,
    options: [r`ApoB-48 on the chylomicrons, the cofactor the enzyme requires`, r`ApoC-II on the chylomicrons, the cofactor the enzyme requires`, r`Insulin in the plasma, the hormone that induces the enzyme`, r`Colipase on the chylomicrons, the anchor the enzyme requires`],
    correctAnswer: 1,
    explanation: r`The child's enzyme works, so the fault lies in the substrate particle: lipoprotein lipase must be activated by apoC-II carried on the chylomicron. ApoB-48 is the structural protein, and a particle without it could not have formed at all. Insulin raises the amount of enzyme, which is not the problem here, and colipase assists pancreatic lipase in the gut.`,
  },
  [r`Why must adipose tissue obtain glycerol 3-phosphate from glucose (or glyceroneogenesis) to re-esterify fatty acids?`]: {
    question: r`Cultured adipocytes are given fatty acids and free glycerol but no glucose, and they store almost no triacylglycerol. Adding glucose restores storage. Why?`,
    options: [r`Glucose supplies acetyl-CoA; these cells cannot take up fatty acids directly`, r`Glucose supplies NADPH; these cells cannot reduce free glycerol without it`, r`Glucose supplies glycerol 3-phosphate; these cells cannot phosphorylate glycerol`, r`Glucose supplies ATP; these cells cannot make any ATP from fatty acids`],
    correctAnswer: 2,
    explanation: r`Triacylglycerol is built on glycerol 3-phosphate, and adipocytes lack glycerol kinase, so free glycerol is useless to them. They make glycerol 3-phosphate from the glycolytic intermediate DHAP instead, which is why storage depends on glucose. The fatty acids were already supplied and taken up, and neither NADPH nor a shortage of ATP explains the failure to use glycerol.`,
  },
  [r`{{c1::Phospholipase $A_2$}} frees arachidonate; {{c2::COX}} yields prostaglandins/thromboxanes, {{c3::lipoxygenase}} yields leukotrienes.`]: {
    question: r`A new drug selectively inhibits lipoxygenase and has no effect on phospholipase A₂ or cyclooxygenase. Which mediators fall?`,
    options: [r`Prostaglandins fall; leukotrienes and thromboxanes do not`, r`Thromboxanes fall; leukotrienes and prostaglandins do not`, r`All three fall, since arachidonate is no longer released`, r`Leukotrienes fall; prostaglandins and thromboxanes do not`],
    correctAnswer: 3,
    explanation: r`Arachidonate released by phospholipase A₂ goes down two branches: cyclooxygenase makes prostaglandins and thromboxanes, and lipoxygenase makes leukotrienes. Blocking lipoxygenase removes only the leukotrienes. Prostaglandins and thromboxanes both depend on cyclooxygenase, and all three would fall only if phospholipase A₂ were blocked.`,
  },
  [r`Fatty acid notation: {{c1::delta}} numbering counts from the carboxyl carbon, while {{c2::omega}} numbering counts from the methyl end.`]: {
    question: r`A fatty acid is written 20:5 with cis double bonds at delta-5, 8, 11, 14 and 17. To which omega family does it belong?`,
    options: [r`Omega-6, because 20 − 14 = 6`, r`Omega-5, because the first bond is at 5`, r`Omega-17, because the last bond is at 17`, r`Omega-3, because 20 − 17 = 3`],
    correctAnswer: 3,
    explanation: r`Delta numbers count from the carboxyl carbon and omega numbers count from the methyl end, so the omega class is the chain length minus the highest delta position: 20 − 17 = 3. Using 14 picks the wrong double bond. Omega-5 and omega-17 simply reuse delta numbers without converting them to the other end of the chain.`,
  },
  [r`PCSK9 raises plasma LDL because it marks the {{c1::LDL receptor}} for {{c2::lysosomal degradation}} rather than recycling.`]: {
    question: r`A family carries a gain-of-function mutation in PCSK9, so the protein is more active than normal. What is expected in affected members?`,
    options: [r`Fewer LDL receptors on hepatocytes and higher plasma LDL`, r`More LDL receptors on hepatocytes and lower plasma LDL`, r`Fewer LDL receptors on hepatocytes and lower plasma LDL`, r`More LDL receptors on hepatocytes and higher plasma LDL`],
    correctAnswer: 0,
    explanation: r`PCSK9 sends the LDL receptor to the lysosome for destruction instead of letting it recycle to the surface. More PCSK9 activity means fewer receptors and less LDL cleared from blood, a form of familial hypercholesterolemia. More receptors with lower LDL is what loss of PCSK9 or an anti-PCSK9 antibody produces, and the mixed choices break the link between receptor number and LDL clearance.`,
  },
  [r`Vitamin D activation: skin converts {{c1::7-dehydrocholesterol}} under UV light, the liver adds a hydroxyl at {{c2::25}}, and the kidney adds one at {{c3::1}}.`]: {
    question: r`A patient with chronic kidney failure has a healthy liver, eats well and gets regular sunlight. Which pattern of vitamin D forms is expected in blood?`,
    options: [r`Low 25-hydroxy form, normal 1,25-dihydroxy form`, r`Normal 25-hydroxy form, high 1,25-dihydroxy form`, r`Normal 25-hydroxy form, low 1,25-dihydroxy form`, r`Low 25-hydroxy form, high 1,25-dihydroxy form`],
    correctAnswer: 2,
    explanation: r`Skin makes the vitamin from 7-dehydrocholesterol and the liver adds the hydroxyl at carbon 25, and both steps are intact here. The kidney adds the hydroxyl at carbon 1, so kidney failure leaves the active 1,25-dihydroxy form low. A low 25-hydroxy form would point to poor intake, little sunlight or liver disease, and a failing kidney cannot raise the 1,25 form.`,
  },
  [r`Glucocorticoids block eicosanoids upstream by inhibiting {{c1::phospholipase $A_2$}}, shutting down {{c2::both prostaglandin and leukotriene}} branches.`]: {
    question: r`A patient with asthma wheezes more after taking ibuprofen, an inhibitor of cyclooxygenase. Why does a glucocorticoid not carry the same risk?`,
    options: [r`It blocks cyclooxygenase too, but binds it only reversibly`, r`It blocks lipoxygenase alone, leaving prostaglandins untouched`, r`It blocks the leukotriene receptor on airway smooth muscle`, r`It blocks phospholipase A₂, cutting off both eicosanoid branches`],
    correctAnswer: 3,
    explanation: r`Inhibiting cyclooxygenase alone can divert arachidonate into the lipoxygenase branch and raise leukotrienes, which constrict airways. Glucocorticoids act upstream by inhibiting phospholipase A₂, so no arachidonate is released for either branch. They are not cyclooxygenase or lipoxygenase inhibitors, and blocking the leukotriene receptor is how montelukast works.`,
  },
  [r`Why do pancreatic insufficiency and biliary obstruction cause deficiency of vitamins A, D, E, and K?`]: {
    question: r`A patient with cystic fibrosis and pancreatic insufficiency has bulky fatty stools, bruises easily and has a prolonged prothrombin time. What explains the clotting problem?`,
    options: [r`Vitamin C is lost in stool along with unabsorbed fat`, r`Vitamin K is no longer synthesized by the pancreas`, r`Vitamin K is lost in stool along with unabsorbed fat`, r`Vitamin B12 is no longer carried by bile salt micelles`],
    correctAnswer: 2,
    explanation: r`Vitamins A, D, E and K are absorbed with dietary fat through micelles, so when fat is not digested they are lost in stool, and low vitamin K shows up as a prolonged prothrombin time. Vitamin C is water-soluble and absorbed without fat. The pancreas does not make vitamin K, and B12 absorption does not use micelles or control prothrombin time.`,
  },
  [r`How does a bile acid sequestrant such as cholestyramine lower plasma LDL?`]: {
    question: r`A patient starts cholestyramine, a resin that binds bile acids in the gut. Which pair of changes in the liver follows?`,
    options: [r`Bile acid synthesis falls and LDL receptor numbers rise`, r`Bile acid synthesis rises and LDL receptor numbers fall`, r`Bile acid synthesis rises and LDL receptor numbers rise`, r`Bile acid synthesis falls and LDL receptor numbers fall`],
    correctAnswer: 2,
    explanation: r`Bound bile acids are excreted instead of being recycled, so the liver must make more from cholesterol. The drop in hepatic cholesterol raises LDL receptor expression, and the extra receptors pull LDL out of blood. Falling bile acid synthesis is the opposite of what losing bile acids causes, and falling receptor numbers would raise plasma LDL.`,
  },
  [r`Why can fatty acids not yield net glucose, and what are the narrow exceptions?`]: {
    question: r`During a long fast, a person breaks down stored tripalmitin, a triacylglycerol with three palmitate (16:0) chains on glycerol. Which part of the molecule can give a net gain of glucose?`,
    options: [r`Only the glycerol backbone, which enters as DHAP`, r`Only the palmitate chains, which enter as acetyl-CoA`, r`Both the glycerol backbone and the palmitate chains`, r`Neither the glycerol backbone nor the palmitate chains`],
    correctAnswer: 0,
    explanation: r`Glycerol is phosphorylated in the liver and enters gluconeogenesis as DHAP. Palmitate has an even number of carbons, so it yields only acetyl-CoA, which cannot go back to pyruvate, and its two carbons are matched by two CO₂ lost in the citric acid cycle. Only odd-chain fatty acids contribute, through propionyl-CoA, and palmitate is not one.`,
  },
  [r`Fat yields about {{c1::9}} kcal/g versus about {{c2::4}} for carbohydrate and protein, and fat is stored {{c3::anhydrous}} while glycogen is hydrated.`]: {
    question: r`A snack bar contains 10 g of fat, 20 g of carbohydrate and 5 g of protein. About how much energy does it provide?`,
    options: [r`140 kcal`, r`190 kcal`, r`215 kcal`, r`315 kcal`],
    correctAnswer: 1,
    explanation: r`Fat gives about 9 kcal/g and carbohydrate and protein about 4 kcal/g, so the bar provides 90 + 80 + 20 = 190 kcal. A total of 140 uses 4 kcal/g for everything, and 315 uses 9 kcal/g for everything. A total of 215 gives protein the fat value by mistake.`,
  },
  [r`Distinguish diabetic ketoacidosis from starvation ketosis.`]: {
    question: r`Two patients have ketones in their blood. Patient 1 has glucose 480 mg/dL and arterial pH 7.10. Patient 2 has glucose 65 mg/dL and arterial pH 7.36. What is the best interpretation?`,
    options: [r`Patient 1 has starvation ketosis; patient 2 has diabetic ketoacidosis`, r`Both have diabetic ketoacidosis, with patient 2 at an earlier stage`, r`Both have starvation ketosis, with patient 1 at a later stage`, r`Patient 1 has diabetic ketoacidosis; patient 2 has starvation ketosis`],
    correctAnswer: 3,
    explanation: r`With essentially no insulin, lipolysis and ketone production run unchecked while glucose is high, giving severe acidosis as in patient 1. In starvation, the remaining insulin limits ketone output, so glucose is low or normal and pH stays near normal as in patient 2. Starvation never produces a glucose of 480 mg/dL, and ketoacidosis from insulin lack does not present with a glucose of 65.`,
  },
  [r`Aspirin inhibits cyclooxygenase {{c1::irreversibly}} by acetylation, which silences {{c2::platelets}} for their entire lifespan.`]: {
    question: r`After one low dose of aspirin, platelet thromboxane production stays suppressed for about a week, while prostacyclin production by endothelial cells recovers within a day. Why the difference?`,
    options: [r`Platelets take up far more of the drug than endothelial cells do`, r`Aspirin binds reversibly in platelets and irreversibly elsewhere`, r`Platelets have no nucleus to make new enzyme; endothelial cells do`, r`Endothelial cells make prostacyclin with lipoxygenase instead`],
    correctAnswer: 2,
    explanation: r`Aspirin acetylates cyclooxygenase irreversibly, so activity returns only when new enzyme is synthesized. Platelets lack a nucleus and cannot do that, so the effect lasts their whole lifespan, while endothelial cells replace the enzyme. The binding is irreversible in every cell, drug uptake is not the reason, and prostacyclin is a cyclooxygenase product.`,
  },
  [r`How does chronic alcohol use produce a fatty liver?`]: {
    question: r`After a night of heavy drinking, ethanol oxidation has driven the hepatocyte NADH/NAD⁺ ratio very high. Which pair of effects explains why triacylglycerol builds up in the liver?`,
    options: [r`β-Oxidation slows, and glycerol 3-phosphate formation rises`, r`β-Oxidation speeds up, and glycerol 3-phosphate formation rises`, r`β-Oxidation slows, and glycerol 3-phosphate formation falls`, r`β-Oxidation speeds up, and glycerol 3-phosphate formation falls`],
    correctAnswer: 0,
    explanation: r`High NADH inhibits the NAD⁺-dependent steps of β-oxidation and the citric acid cycle, and it pushes DHAP toward glycerol 3-phosphate. Fatty acids that cannot be burned are esterified onto that glycerol 3-phosphate and stored. Faster β-oxidation would need more NAD⁺, not less, and less glycerol 3-phosphate would limit triacylglycerol formation.`,
  },
  [r`Abetalipoproteinemia is loss of {{c1::microsomal triglyceride transfer protein}}, so neither {{c2::chylomicrons}} nor VLDL can be assembled.`]: {
    question: r`An infant has fatty stools. After a fatty meal, intestinal cells are packed with lipid droplets, yet no chylomicrons appear in plasma, and plasma triacylglycerol is nearly zero even when fasting. Which protein is defective?`,
    options: [r`Lipoprotein lipase, so chylomicrons and VLDL are not cleared from blood`, r`Microsomal triglyceride transfer protein, so no chylomicrons or VLDL form`, r`Pancreatic lipase, so dietary fat is never digested or taken up by cells`, r`The LDL receptor, so chylomicron remnants and LDL stay in the plasma`],
    correctAnswer: 1,
    explanation: r`Fat inside the enterocytes shows that digestion and uptake work, and the block is in loading triacylglycerol onto apoB, the job of microsomal triglyceride transfer protein. Neither chylomicrons nor VLDL can be assembled, so plasma triacylglycerol is almost absent. Lipoprotein lipase or LDL receptor defects raise plasma lipids, and without pancreatic lipase the fat would never reach the cells.`,
  },
  [r`Contrast familial chylomicronemia with familial hypercholesterolemia in what accumulates and what it causes.`]: {
    question: r`A 25-year-old has firm nodules on both Achilles tendons and a pale ring at the edge of each cornea, and his father had a heart attack at 38. His fasting plasma is clear, not milky. What accumulates, and why?`,
    options: [r`LDL, from loss of functional LDL receptors`, r`Chylomicrons, from loss of lipoprotein lipase`, r`LDL, from loss of functional apoC-II`, r`Chylomicrons, from loss of LDL receptors`],
    correctAnswer: 0,
    explanation: r`Tendon xanthomas, corneal arcus and early coronary disease with clear plasma mark familial hypercholesterolemia, in which LDL receptors are lost and LDL accumulates. Loss of lipoprotein lipase or apoC-II leaves chylomicrons in blood, giving milky plasma, eruptive xanthomas and pancreatitis with little atherosclerosis. The mixed choices pair a particle with the wrong defect.`,
  },
  [r`The Friedewald estimate is LDL = total cholesterol - HDL - {{c1::triglycerides}}/5, and it fails once triglycerides exceed about {{c2::400}} mg/dL.`]: {
    question: r`A fasting lipid panel shows total cholesterol 200 mg/dL, HDL 50 mg/dL and triglycerides 150 mg/dL. What is the estimated LDL cholesterol?`,
    options: [r`150 mg/dL`, r`120 mg/dL`, r`135 mg/dL`, r`170 mg/dL`],
    correctAnswer: 1,
    explanation: r`The estimate is total cholesterol minus HDL minus triglycerides divided by 5: 200 − 50 − 30 = 120 mg/dL, and it is valid here because triglycerides are well under 400 mg/dL. An answer of 150 leaves out the triglyceride term, and 170 leaves out HDL. An answer of 135 divides triglycerides by 10 instead of 5.`,
  },
  [r`Why can a urine ketone dipstick understate the severity of early DKA?`]: {
    question: r`A patient in diabetic ketoacidosis is given insulin and fluids. Over six hours the blood pH improves steadily, yet the nitroprusside urine ketone test becomes more strongly positive. What explains this?`,
    options: [r`β-Hydroxybutyrate is building up further, and it is what the test detects`, r`β-Hydroxybutyrate is being oxidized to acetoacetate, which the test detects`, r`Acetoacetate is being reduced to β-hydroxybutyrate, which the test detects`, r`Glucose is spilling into the urine and reacting with the test reagent`],
    correctAnswer: 1,
    explanation: r`Nitroprusside reacts with acetoacetate and acetone but not with β-hydroxybutyrate, the main ketone body when mitochondrial NADH is high. As treatment lowers NADH, β-hydroxybutyrate is converted back to acetoacetate, so the test reads stronger while the patient improves. The test cannot see β-hydroxybutyrate at all, and urine glucose falls with treatment and does not react.`,
  },
  [r`Dietary triglyceride is digested by pancreatic {{c1::lipase}}, which needs {{c2::colipase}} to work on bile-salt micelles and is blocked by {{c3::orlistat}}.`]: {
    question: r`A patient takes orlistat with a high-fat dinner and later passes oily stools. What is the fat in the stool, and why is it there?`,
    options: [r`Free fatty acids, because bile salts are bound in the gut lumen`, r`Intact triacylglycerol, because pancreatic lipase is inhibited`, r`Intact triacylglycerol, because bile secretion is inhibited`, r`Free fatty acids, because chylomicron assembly is inhibited`],
    correctAnswer: 1,
    explanation: r`Orlistat blocks pancreatic lipase, the colipase-dependent enzyme that cuts dietary triacylglycerol into 2-monoacylglycerol and fatty acids, so the fat passes through undigested. Binding bile salts is how a bile acid resin works, and orlistat does not stop bile secretion. A block in chylomicron assembly would trap fat inside intestinal cells after normal digestion.`,
  },
  [r`Bile acid synthesis is rate-limited by {{c1::7-alpha-hydroxylase}}, and the acids are conjugated with {{c2::glycine or taurine}} to lower their pKa.`]: {
    question: r`An unconjugated bile acid has a pKa near 6, and its taurine conjugate has a pKa near 2. In the upper small intestine at about pH 6, why is the conjugate the better detergent?`,
    options: [r`It is almost fully protonated, so it stays dissolved in the lumen`, r`It is almost fully ionized, so it diffuses out across membranes`, r`It is almost fully ionized, so it stays dissolved in the lumen`, r`It is only half ionized, so it can bind fat and water equally`],
    correctAnswer: 2,
    explanation: r`At a pH four units above its pKa, the conjugate is almost entirely in its charged form, which stays in solution in the lumen and cannot slip passively across membranes. Half ionized describes the unconjugated acid, whose pKa equals the pH. A low pKa means deprotonated, not protonated, at pH 6, and a charged molecule does not diffuse through membranes.`,
  },
  [r`Steroid hormone synthesis is rate-limited by cholesterol import into the mitochondrion via {{c1::StAR}}, followed by side-chain cleavage by {{c2::desmolase}}.`]: {
    question: r`A newborn has a mutation that inactivates StAR. The cells of the adrenal cortex are swollen with cholesterol droplets. Which hormones are deficient?`,
    options: [r`All steroid hormones, because no pregnenolone can be made`, r`Only cortisol, because StAR acts in a single adrenal zone`, r`Only aldosterone, because StAR acts in a single adrenal zone`, r`Only sex steroids, because StAR is found only in the gonads`],
    correctAnswer: 0,
    explanation: r`StAR carries cholesterol into the mitochondrion, the rate-limiting step, where desmolase cuts the side chain to make pregnenolone. Every steroid hormone descends from pregnenolone, so all are lost and unused cholesterol piles up. The choices naming a single hormone confuse this shared first step with the later enzymes that decide which hormone a cell makes.`,
  },
}
